const PROTECTED = [2606,2608,2624,2626,2632,2654,2672,1914,1922,3951,3999,4004,
                   7748,7785,8037,7656,7658,1615,1616,8022,114];

(async () => {
  const ids = items.map(i => i[0]);
  const dup = ids.filter((v, i) => ids.indexOf(v) !== i);
  const leak = ids.filter(i => PROTECTED.includes(i));
  if (dup.length || leak.length) {
    console.error('ABORT — dup:', dup, 'A/B 洩漏:', leak);
    process.exit(1);
  }
  console.log(`preflight OK: ${ids.length} 首,冇重複,冇夾帶 A/B 類`);

  let ok = 0;
  for (const [id, reason] of items) {
    try {
      const r = await delistHymn(id);
      ok++;
      console.log(`OK ${id} | ${r.hymn.org} | ${r.hymn.title} | ${reason} | before=${JSON.stringify(r.before)} idem=${!!r.idempotent}`);
    } catch (e) {
      console.log(`FAIL ${id} | ${reason} | ${e.code || e.message}`);
    }
  }
  console.log('DONE', ok, '/', items.length);
  process.exit(0);
})().catch((e) => { console.error('ERROR', e); process.exit(1); });
